// ─── SOUND & HAPTICS (synthesised via Web Audio — no audio files needed) ─────
// All calls are wrapped in try/catch so the app runs silently if audio is
// unavailable. Sounds only start after a user tap, which satisfies mobile
// autoplay rules. Vibration works on Android; iPhones ignore it gracefully.
const Sfx = (() => {
  let ctx = null;
  let muted = false;
  try { muted = window.localStorage.getItem("man3131_muted") === "1"; } catch (e) {}
  const ensure = () => {
    if (!ctx) { try { ctx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) {} }
    if (ctx && ctx.state === "suspended") { try { ctx.resume(); } catch (e) {} }
    return ctx;
  };
  const tone = (freq, dur, type = "sine", vol = 0.12, when = 0) => {
    const c = ensure(); if (!c || muted) return;
    try {
      const o = c.createOscillator(); const g = c.createGain();
      o.type = type; o.frequency.value = freq;
      g.gain.setValueAtTime(vol, c.currentTime + when);
      g.gain.exponentialRampToValueAtTime(0.001, c.currentTime + when + dur);
      o.connect(g); g.connect(c.destination);
      o.start(c.currentTime + when); o.stop(c.currentTime + when + dur + 0.05);
    } catch (e) {}
  };
  return {
    isMuted: () => muted,
    setMuted: (m) => { muted = m; try { window.localStorage.setItem("man3131_muted", m ? "1" : "0"); } catch (e) {} },
    correct: () => { tone(660, 0.1, "sine", 0.1); tone(880, 0.16, "sine", 0.1, 0.08); },
    wrong: () => { tone(200, 0.18, "sawtooth", 0.06); tone(160, 0.22, "sawtooth", 0.06, 0.09); },
    gavel: () => { tone(110, 0.09, "square", 0.16); tone(70, 0.12, "square", 0.1, 0.02); },
    fanfare: () => { [523, 659, 784, 1047].forEach((f, i) => tone(f, 0.22, "triangle", 0.1, i * 0.11)); },
    vibrate: (pattern) => { try { if (navigator.vibrate) navigator.vibrate(pattern); } catch (e) {} }
  };
})();

