function Particles({ active, color, type }) {
  const canvasRef = useRef(null);
  const animRef = useRef(null);
  const parts = useRef([]);
  useEffect(() => {
    if (!active) return;
    const c = canvasRef.current; if (!c) return;
    const ctx = c.getContext("2d");
    c.width = c.offsetWidth; c.height = c.offsetHeight;
    const count = type === "correct" ? 60 : 20;
    parts.current = Array.from({ length: count }, () => ({
      x: c.width / 2 + (Math.random() - 0.5) * 200, y: c.height / 2,
      vx: (Math.random() - 0.5) * (type === "correct" ? 8 : 4),
      vy: -Math.random() * (type === "correct" ? 12 : 6) - 2,
      size: Math.random() * (type === "correct" ? 8 : 5) + 2, alpha: 1,
      color: type === "correct" ? [color, "#FFD700", "#FFFFFF"][Math.floor(Math.random() * 3)] : ["#C06B6B", "#8B3333"][Math.floor(Math.random() * 2)],
      shape: ["circle", "star", "rect"][Math.floor(Math.random() * 3)],
      rot: Math.random() * Math.PI * 2, rotV: (Math.random() - 0.5) * 0.2
    }));
    const draw = () => {
      ctx.clearRect(0, 0, c.width, c.height);
      let alive = false;
      parts.current.forEach(p => {
        if (p.alpha <= 0) return; alive = true;
        p.x += p.vx; p.y += p.vy; p.vy += 0.3; p.alpha -= 0.02; p.rot += p.rotV;
        ctx.save(); ctx.globalAlpha = Math.max(0, p.alpha); ctx.fillStyle = p.color;
        ctx.translate(p.x, p.y); ctx.rotate(p.rot);
        if (p.shape === "circle") { ctx.beginPath(); ctx.arc(0, 0, p.size, 0, Math.PI * 2); ctx.fill(); }
        else if (p.shape === "rect") ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
        else { ctx.beginPath(); for (let i = 0; i < 5; i++) { const a = (i * Math.PI * 4) / 5 - Math.PI / 2; const r = i % 2 === 0 ? p.size : p.size / 2; i === 0 ? ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r) : ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r); } ctx.closePath(); ctx.fill(); }
        ctx.restore();
      });
      if (alive) animRef.current = requestAnimationFrame(draw);
    };
    animRef.current = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(animRef.current);
  }, [active, color, type]);
  if (!active) return null;
  return <canvas ref={canvasRef} style={{ position: "fixed", top: 0, left: 0, width: "100%", height: "100%", pointerEvents: "none", zIndex: 999 }} />;
}

function ScoreCounter({ value }) {
  const [display, setDisplay] = useState(value);
  const prev = useRef(value);
  useEffect(() => {
    if (value === prev.current) return;
    const diff = value - prev.current; let i = 0;
    const iv = setInterval(() => { i++; setDisplay(Math.round(prev.current + (diff * i) / 20)); if (i >= 20) { clearInterval(iv); prev.current = value; } }, 20);
    return () => clearInterval(iv);
  }, [value]);
  return <span>{display}</span>;
}

function XPToast({ amount, visible }) {
  return (
    <div style={{ position: "fixed", top: 80, right: 20, zIndex: 1000, background: "linear-gradient(135deg,#C9A84C,#FFD700)", color: "#0A0A0F", fontWeight: 700, fontSize: 18, padding: "10px 18px", borderRadius: 50, fontFamily: "'Playfair Display',serif", boxShadow: "0 4px 20px #C9A84C66", transform: visible ? "translateY(0) scale(1)" : "translateY(-20px) scale(0.8)", opacity: visible ? 1 : 0, transition: "all 0.4s cubic-bezier(0.34,1.56,0.64,1)", pointerEvents: "none" }}>+{amount} pts ⚡</div>
  );
}

function StreakBanner({ streak, visible }) {
  if (!visible || streak < 2) return null;
  const msgs = { 2: "2× Streak! 🔥", 3: "On Fire! 🔥🔥", 4: "Unstoppable! ⚡🔥", 5: "Status Scholar! 🎓" };
  return (
    <div style={{ position: "fixed", top: 130, left: "50%", transform: "translateX(-50%)", background: "linear-gradient(135deg,#E07B39,#C9A84C)", color: "#fff", fontWeight: 700, fontSize: 16, padding: "10px 24px", borderRadius: 50, zIndex: 1000, fontFamily: "'Playfair Display',serif", boxShadow: "0 4px 24px #E07B3966", animation: "streakPop 0.5s cubic-bezier(0.34,1.56,0.64,1) both", pointerEvents: "none" }}>{msgs[Math.min(streak, 5)] || `${streak}× Streak! 🔥`}</div>
  );
}

function GavelStrike({ visible }) {
  return <div style={{ position: "fixed", top: "50%", left: "50%", transform: "translate(-50%,-50%)", fontSize: 80, zIndex: 1001, opacity: visible ? 1 : 0, animation: visible ? "gavelStrike 0.6s ease both" : "none", pointerEvents: "none" }}>🔨</div>;
}

