          {/* badge */}
          <div style={{ animation: "haloFloat 4s ease-in-out infinite", position: "relative", zIndex: 2 }}>
            <img src={BADGE_IMG} alt="Employment Law — MAN3131 2026" width={188} height={188} style={{ display: "block", borderRadius: "50%", filter: "drop-shadow(0 10px 30px rgba(0,0,0,0.6))" }} />
          </div>
